"use client";

import type { ReactNode } from "react";

type MotionProps = {
  children: ReactNode;
  className?: string;
  entrance?: string;
  delayMs?: number;
};

const PRESET = "nexus-grid-reveal";
const REDUCED_MOTION = "fade";
const DEFAULT_DURATION = 520;

const ENTRANCE_TYPES: Record<string, string> = {
  "hero": "grid-stagger",
  "section": "slide-up",
  "metric": "count-up",
};

export function Motion({ children, className = "", entrance, delayMs = 0 }: MotionProps) {
  const motionType = entrance ? ENTRANCE_TYPES[entrance] ?? "fade-in" : "fade-in";
  const duration = DEFAULT_DURATION;

  return (
    <div
      className={["v2-motion", className].filter(Boolean).join(" ")}
      data-v2-motion={PRESET}
      data-entrance={motionType}
      style={{
        animation: `${motionType} ${duration}ms cubic-bezier(0.22, 1, 0.36, 1) both`,
        animationDelay: `${delayMs}ms`,
      }}
    >
      {children}
    </div>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Template Architecture V2 — saas-enterprise · spec 2.0.0 */
:root {
  --v2-package: "saas-enterprise";
  --color-primary: #1D4ED8;
  --color-secondary: #1E293B;
  --color-accent: #3B82F6;
  --color-background: #F8FAFC;
  --color-foreground: #0F172A;
  --color-muted: rgba(15,23,42,0.58);
  --color-surface: #FFFFFF;
  --color-signal: #059669;
  --color-grid: rgba(15,23,42,0.06);
  --color-ink: #020617;
  --font-display: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --font-body: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --spacing-unit: 0.25rem;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-surface: 0 1px 3px rgba(15,23,42,0.06), 0 12px 40px rgba(15,23,42,0.08);
  --shadow-glow: 0 0 80px rgba(59,130,246,0.18);
  --shadow-card: 0 0 0 1px rgba(15,23,42,0.04), 0 4px 24px rgba(15,23,42,0.06);
  --border-default: rgba(15,23,42,0.08);
  --border-accent: rgba(59,130,246,0.24);
  --border-subtle: rgba(15,23,42,0.04);
}

/* V2 language profile — RTL typography adaptation */
[dir="rtl"] {
  --font-display: Cairo, ui-serif, Georgia, serif;
  --font-body: "IBM Plex Sans Arabic", ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.01em;
}

@import url("https://fonts.googleapis.com/css2?family=Cairo:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans+Arabic:wght@400;500;600&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&family=Plus+Jakarta+Sans:ital,wght@0,500;0,600;0,700;0,800;1,500&display=swap");

@keyframes se-grid-reveal {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes se-slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes se-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
[dir="rtl"] [class*="se-marquee"],
[dir="rtl"] [class*="cb-marquee"] {
  animation-direction: reverse;
}
@keyframes se-pulse-dot {
  0%, 100% { opacity: 0.4; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1); }
}
@keyframes se-scan-line {
  0% { transform: translateY(-100%); opacity: 0; }
  50% { opacity: 0.06; }
  100% { transform: translateY(100vh); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .se-animate, [data-se-motion] { animation: none !important; transition: none !important; }
}

.se-font-display { font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif; }
.se-font-body { font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif; }
.se-font-mono { font-family: "IBM Plex Mono", ui-monospace, monospace; }
.se-eyebrow {
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-accent, #3B82F6);
}
.se-headline {
  font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif;
  font-size: clamp(2.25rem, 4.5vw, 3.75rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--color-foreground);
  text-wrap: balance;
}
.se-headline-sm {
  font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif;
  font-size: clamp(1.5rem, 2.8vw, 2.25rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.025em;
  color: var(--color-foreground);
  text-wrap: balance;
}
.se-body {
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 1.0625rem;
  line-height: 1.65;
  color: var(--color-muted, rgba(15,23,42,0.58));
}
.se-grid-bg {
  background-image:
    linear-gradient(var(--color-grid, rgba(15,23,42,0.06)) 1px, transparent 1px),
    linear-gradient(90deg, var(--color-grid, rgba(15,23,42,0.06)) 1px, transparent 1px);
  background-size: 48px 48px;
}
.se-card {
  border: 1px solid var(--border-subtle, rgba(15,23,42,0.04));
  background: var(--color-surface);
  border-radius: var(--radius-lg, 16px);
  box-shadow: var(--shadow-card);
  transition: box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1), transform 0.35s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.35s ease;
}
.se-card:hover {
  box-shadow: var(--shadow-surface);
  border-color: var(--border-accent, rgba(59,130,246,0.24));
  transform: translateY(-2px);
}
.se-card-featured {
  border-color: var(--border-accent, rgba(59,130,246,0.28));
  background: linear-gradient(165deg, color-mix(in srgb, var(--color-accent) 5%, var(--color-surface)), var(--color-surface));
  box-shadow: var(--shadow-surface), 0 0 0 1px color-mix(in srgb, var(--color-accent) 12%, transparent);
}
.se-section-alt {
  background: linear-gradient(180deg, var(--color-surface) 0%, var(--color-background) 100%);
}
.se-section-glow {
  position: relative;
  isolation: isolate;
}
.se-section-glow::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 90% 55% at 50% -15%, color-mix(in srgb, var(--color-accent) 9%, transparent), transparent 68%);
}
.se-glow-orb {
  pointer-events: none;
  position: absolute;
  border-radius: 50%;
  filter: blur(64px);
  opacity: 0.45;
}
.se-browser-frame {
  border: 1px solid var(--border-default, rgba(15,23,42,0.08));
  border-radius: var(--radius-xl, 20px);
  background: var(--color-surface);
  box-shadow: var(--shadow-surface), 0 0 0 1px color-mix(in srgb, var(--color-accent) 8%, transparent);
  overflow: hidden;
}
.se-browser-chrome {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  border-bottom: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--color-foreground) 3%, var(--color-surface));
  padding: 0.625rem 0.875rem;
}
.se-browser-dot {
  height: 0.5rem;
  width: 0.5rem;
  border-radius: 50%;
  background: var(--border-default);
}
.se-trust-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.25rem 1.75rem;
}
.se-trust-logo {
  font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif;
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: color-mix(in srgb, var(--color-foreground) 42%, transparent);
  transition: color 0.25s ease;
}
.se-trust-logo:hover { color: var(--color-foreground); }
.se-trust-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  border-radius: 9999px;
  border: 1px solid var(--border-default);
  background: color-mix(in srgb, var(--color-surface) 88%, transparent);
  padding: 0.25rem 0.625rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--color-muted);
  backdrop-filter: blur(8px);
}
.se-star {
  color: var(--color-signal, #059669);
  letter-spacing: 0.12em;
}
.se-quote-mark {
  font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif;
  font-size: 3.5rem;
  line-height: 1;
  color: color-mix(in srgb, var(--color-accent) 35%, transparent);
}
.se-divider-gradient {
  height: 1px;
  width: 100%;
  background: linear-gradient(90deg, transparent, var(--border-default), transparent);
}
.se-input,
.se-textarea {
  width: 100%;
  border-radius: var(--radius-md, 10px);
  border: 1px solid var(--border-default);
  background: var(--color-background);
  padding: 0.625rem 0.875rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  color: var(--color-foreground);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.se-input:focus-visible,
.se-textarea:focus-visible {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-accent) 18%, transparent);
}
.se-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.75rem 1.5rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  color: #fff;
  background: var(--color-primary, #1D4ED8);
  border-radius: var(--radius-md, 10px);
  border: 1px solid transparent;
  box-shadow: 0 1px 2px rgba(15,23,42,0.06);
  transition: background 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
}
.se-btn-primary:hover {
  background: var(--color-accent, #3B82F6);
  box-shadow: var(--shadow-glow);
  transform: translateY(-1px);
}
.se-btn-primary:active {
  transform: translateY(0) scale(0.98);
}
.se-btn-primary:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.se-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.75rem 1.5rem;
  font-family: var(--font-body), "IBM Plex Sans", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  color: var(--color-foreground);
  background: var(--color-surface);
  border: 1px solid var(--border-default, rgba(15,23,42,0.08));
  border-radius: var(--radius-md, 10px);
  transition: border-color 0.25s ease, background 0.25s ease;
}
.se-btn-secondary:hover { border-color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 4%, var(--color-surface)); transform: translateY(-1px); }
.se-btn-secondary:active { transform: translateY(0) scale(0.98); }
.se-btn-secondary:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.se-section { padding-block: clamp(4rem, 10vw, 6.5rem); }
.se-metric {
  font-family: var(--font-display), "Plus Jakarta Sans", system-ui, sans-serif;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-primary);
}
.se-signal { color: var(--color-signal, #059669); }
.se-focus-ring:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

