/* TBDP Experience — motion, interaction, RTL, accessibility */
/* TBDP Phase 3 — Motion System · tbdp-xp */

@keyframes tbdp-xp-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes tbdp-xp-fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

@keyframes tbdp-xp-rise {
  from { opacity: 0; transform: translateY(var(--tbdp-spacing-lg)); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes tbdp-xp-rise-rtl {
  from { opacity: 0; transform: translateX(var(--tbdp-spacing-lg)); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes tbdp-xp-scale-in {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes tbdp-xp-slide-end {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes tbdp-xp-slide-start {
  from { transform: translateX(-100%); }
  to { transform: translateX(0); }
}

@keyframes tbdp-xp-shake {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(calc(var(--tbdp-spacing-sm) * -1)); }
  40%, 80% { transform: translateX(var(--tbdp-spacing-sm)); }
}

@keyframes tbdp-xp-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}

@keyframes tbdp-xp-lift {
  to { transform: translateY(calc(var(--tbdp-spacing-sm) * -1)); box-shadow: var(--tbdp-shadow-2); }
}

@media (prefers-reduced-motion: reduce) {
  [data-tbdp-xp-motion] { animation: none !important; transition: none !important; }
}

[data-tbdp-xp-motion] { will-change: transform, opacity; }
[data-tbdp-xp-motion="page-enter"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="page-exit"] { animation-name: tbdp-xp-fade-out; }
[data-tbdp-xp-motion="section-reveal"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="hero-headline"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="hero-media"] { animation-name: tbdp-xp-scale-in; }
[data-tbdp-xp-motion="card-lift"] { animation-name: tbdp-xp-lift; }
[data-tbdp-xp-motion="grid-stagger"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="modal-enter"] { animation-name: tbdp-xp-scale-in; }
[data-tbdp-xp-motion="modal-exit"] { animation-name: tbdp-xp-fade-out; }
[data-tbdp-xp-motion="drawer-slide"] { animation-name: tbdp-xp-slide-end; }
[data-tbdp-xp-motion="toast-enter"] { animation-name: tbdp-xp-rise; }
[data-tbdp-xp-motion="toast-exit"] { animation-name: tbdp-xp-fade-out; }
