  metrics = DEFAULT_METRICS,
}: SaasEnterpriseHeroProps) {
  const src =
    resolveSiteImage(imageUrl || HERO_IMAGE, 0) || SAAS_ENTERPRISE_IMAGES.dashboard;

  return (
    <section
      id="top"
      data-v2-component="saas-enterprise-hero"
