      className="se-section se-section-glow relative min-h-[min(92vh,56rem)] overflow-hidden bg-[var(--color-background)] py-16 sm:py-20 lg:py-24"
    >
      <div className="se-grid-bg pointer-events-none absolute inset-0 opacity-50" aria-hidden />
      <div className="se-glow-orb start-1/4 top-0 h-72 w-72 bg-[var(--color-accent)]" aria-hidden />
      <div className="se-glow-orb end-0 top-1/3 h-56 w-56 bg-[var(--color-primary)]" aria-hidden />

      <div className="relative mx-auto max-w-[82rem] px-5 sm:px-8">
        <div className="grid gap-12 lg:grid-cols-[1.05fr_0.95fr] lg:items-center lg:gap-16">
          <div className="max-w-xl">
            <p className="se-eyebrow mb-4 motion-safe:animate-[se-slide-up_0.6s_ease_both]">{eyebrow}</p>
            <h1
              id="se-hero-title"
              className="se-headline motion-safe:animate-[se-slide-up_0.65s_ease_0.08s_both]"
            >
              {title}
            </h1>
            <p className="se-body text-muted-foreground mt-6 max-w-lg motion-safe:animate-[se-slide-up_0.65s_ease_0.16s_both]">
              {subtitle}
            </p>
            <div className="mt-9 flex flex-wrap gap-3 motion-safe:animate-[se-slide-up_0.65s_ease_0.24s_both]">
              <a href="#contact" className="se-btn-primary se-focus-ring">
                {primaryCta}
              </a>
              <a href="/platform" className="se-btn-secondary se-focus-ring">
                {secondaryCta}
              </a>
            </div>
            <div className="mt-10 space-y-5 motion-safe:animate-[se-slide-up_0.65s_ease_0.32s_both]">
              <div className="flex flex-wrap items-center gap-3">
                <span className="se-trust-badge">
                  <span className="h-1.5 w-1.5 rounded-full bg-[var(--color-signal)] motion-safe:animate-[se-pulse-dot_2s_ease-in-out_infinite]" aria-hidden />
                  Live platform status
                </span>
                <span className="se-font-body text-xs text-[var(--color-muted)]">
                  SOC 2 Type II · GDPR · SSO
                </span>
              </div>
              <div>
                <p className="se-font-body mb-3 text-[0.625rem] font-semibold uppercase tracking-[0.14em] text-[var(--color-muted)]">
                  Trusted by GTM teams at
                </p>
                <div className="se-trust-strip" aria-label="Trusted by leading companies">
                  {TRUST_BRANDS.map((brand) => (
                    <span key={brand.name} className="se-trust-logo inline-flex items-center gap-2">
                      <span
                        className="flex h-6 w-6 items-center justify-center rounded-md bg-[color-mix(in_srgb,var(--color-foreground)_6%,transparent)] text-[0.625rem] font-bold text-[var(--color-muted)]"
                        aria-hidden
                      >
                        {brand.mark}
                      </span>
                      {brand.name}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="motion-safe:animate-[se-grid-reveal_0.85s_ease_0.15s_both]">
            <div className="se-browser-frame">
              <div className="se-browser-chrome" aria-hidden>
                <span className="se-browser-dot" />
                <span className="se-browser-dot" />
                <span className="se-browser-dot" />
                <span className="se-font-mono ms-2 text-[0.625rem] text-[var(--color-muted)]">
                  app.northline.io
                </span>
              </div>
              <img
                src={src}
                alt="Northline revenue command dashboard with pipeline analytics and forecast charts"
                className="aspect-[16/10] w-full object-cover object-top"
                fetchPriority="high"
              />
            </div>
            <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
              {metrics.map((metric, i) => (
                <div
                  key={metric.label}
                  className="se-card p-4 motion-safe:animate-[se-grid-reveal_0.6s_ease_both]"
                  style={{ animationDelay: `${0.35 + i * 0.07}s` }}
                >
                  <p className="se-metric text-2xl">{metric.value}</p>
                  <p className="se-font-body mt-1 text-[0.6875rem] text-[var(--color-muted)]">{metric.label}</p>
                  {metric.trend ? (
                    <p className="se-font-mono mt-0.5 text-[0.625rem] text-[var(--color-signal)]">{metric.trend}</p>
                  ) : null}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

